	["{npc:16032}: choose your reward"] = "{npc:16032}: выберите награду",

	-- Step 28: The Instigator's Enchantment
	-- {npc:16032} Falrin Treeshaper · {item:22224} Jeering Spectre's Essence · {npc:11496} Immol'thar · {area:2057} Scholomance · {item:13704} Skeleton Key
	-- plural, as words: Eldreth Seethers = {npc:11469} Eldreth Seether · Dark Runes = {item:20520} Dark Rune · Large Brilliant Shards = {item:14344} Large Brilliant Shard
	["{npc:16032} wants a {item:22224} (the Eldreth ghosts of Dire Maul West, best the Eldreth Seethers, and the invisible spectres around {npc:11496}'s prison), 4 Dark Runes (the necromancers and summoners of {area:2057}, whose gate opens to a {item:13704}: one in the group is enough; or the auction house) and 8 Large Brilliant Shards (enchanters, or the auction house)."] = "{npc:16032} просит {item:22224} (призраки Элдрета в западной части Забытого города, лучше всего — кипящие духи Элдрета, а также невидимые призраки вокруг темницы {npc:11496}), 4 темные руны (некроманты и призыватели в подземелье {area:2057}, ворота которого открывает {item:13704}: достаточно одного на группу; или аукцион) и 8 больших сверкающих осколков (зачарователи или аукцион).",

	-- Step 29: The Challenge
	-- {npc:16032} Falrin Treeshaper · {item:21986} Banner of Provocation · {area:1584} Blackrock Depths
	-- was: ["{npc:16032} finishes the {item:21986}: plant it in the Ring of Law in {area:1584}."] = "{npc:16032} завершает {item:21986}: установите его на Арене Закона в месте {area:1584}."
	["{npc:16032} finishes the {item:21986}, for the Ring of Law in {area:1584}."] = "",

	-- Step 30: Blackrock Depths: the Ring of Law
	-- {area:1584} Blackrock Depths
	["{area:1584}: the Ring of Law"] = "{area:1584}: Круг Закона",
	-- {area:1584} Blackrock Depths · {area:254} Blackrock Mountain · {zone:1427} Searing Gorge · {zone:1428} Burning Steppes · {npc:10096} High Justice Grimstone · {item:21986} Banner of Provocation · {npc:16059} Theldren · {item:22047} Top Piece of Lord Valthalak's Amulet
	["{area:1584} is the dungeon inside {area:254}, between the {zone:1427} and the {zone:1428}; a group of five. Walk into the Ring of Law so {npc:10096} sentences you, and while he reads the sentence plant the {item:21986} in the middle of the ring. After the first wave, {npc:16059} and his gladiators come instead of the usual boss: five elites who fight like players (crowd control, dispels, no taunts). Kill them all; {npc:16059} drops the {item:22047}."] = "{area:1584} — подземелье внутри места {area:254}, между зонами {zone:1427} и {zone:1428}; группа из пяти. Войдите в Круг Закона, чтобы {npc:10096} вынес вам приговор, и пока он его зачитывает, установите {item:21986} в центре круга. После первой волны вместо обычного босса приходят {npc:16059} и его гладиаторы: пятеро элитных противников, которые сражаются как игроки (контроль, рассеивание, без провокации). Убейте всех; с {npc:16059} падает {item:22047}.",
	-- {item:21986} Banner of Provocation
	["{item:21986}, in the ring"] = "{item:21986} в круге",

	-- Step 31: Anthion Harmon: Anthion's Parting Words
	-- {npc:16016} Anthion Harmon · {area:2279} Stratholme · {quest:84183} Anthion's Parting Words · {item:16691} Devout Sandals · {npc:10438} Maleki the Pallid · {item:16694} Devout Skirt · {npc:10440} Baron Rivendare · {item:16695} Devout Mantle · {npc:10264} Solakar Flamewreath
	["Back to {npc:16016} at {area:2279}'s gate (Ghost Revealer). {quest:84183} takes your {item:16691}: {npc:10438} in {area:2279} (about 18%), your {item:16694}: {npc:10440} in {area:2279} (about 10%), and your {item:16695}: {npc:10264} in Upper Blackrock Spire (about 18%)."] = "Обратно к {npc:16016} у ворот подземелья {area:2279} (Обнаружитель призраков). {quest:84183} забирает {item:16691}: {npc:10438} в подземелье {area:2279} (около 18%), {item:16694}: {npc:10440} в подземелье {area:2279} (около 10%), и {item:16695}: {npc:10264} в Верхней части пика Черной горы (около 18%).",

	-- Step 34: Bodley
	-- {npc:16033} Bodley · {area:1583} Blackrock Spire · {area:254} Blackrock Mountain · {quest:8961} Three Kings of Flame · {item:21987} Incendicite of Incendius · {npc:9017} Lord Incendius · {area:1584} Blackrock Depths · {item:21988} Ember of Emberseer · {npc:9816} Pyroguard Emberseer · {item:21989} Cinder of Cynders · {npc:15206} Duke of Cynders · {zone:1451} Silithus · {item:22014} Hallowed Brazier · {faction:529} Argent Dawn
	-- was: ["{npc:16033}'s ghost stands on the ledge before the {area:1583} portal, high inside {area:254}: use the Ghost Revealer there. {quest:8961} wants the {item:21987} ({npc:9017} in {area:1584}), the {item:21988} ({npc:9816} in Upper Blackrock Spire), the {item:21989} (the {npc:15206} in {zone:1451}) and a {item:22014} from the {faction:529}."] = "Призрак {npc:16033} стоит на уступе перед порталом в {area:1583}, высоко внутри {area:254}: используйте там проявитель призраков. Для {quest:8961} нужны {item:21987} ({npc:9017} в месте {area:1584}), {item:21988} ({npc:9816} в Верхней части пика Черной горы), {item:21989} ({npc:15206} в зоне {zone:1451}) и {item:22014} от фракции {faction:529}."
	["{npc:16033}'s ghost stands on the ledge before the {area:1583} portal, high inside {area:254}, and only the Ghost Revealer shows him. {quest:8961} needs the {item:21987} ({npc:9017}, {area:1584}), the {item:21988} ({npc:9816}, Upper Blackrock Spire), the {item:21989} (the {npc:15206}, {zone:1451}) and a {item:22014} from the {faction:529}."] = "",

	-- Step 36: Honored with the Argent Dawn
	-- {faction:529} Argent Dawn
	["Honored with the {faction:529}"] = "«Уважение» у фракции {faction:529}",
	-- {item:22014} Hallowed Brazier · {item:12846} Argent Dawn Commission · {area:2279} Stratholme · {area:2057} Scholomance · {area:2268} Light's Hope Chapel
	["The {item:22014} is sold only at Honored. The Scourge drop Scourgestones for the Argent officers only while the {item:12846} is worn. Every Scourge kill in the Plaguelands counts, {area:2279} and {area:2057} undead give 5 each up to Honored, and {area:2268}'s dungeon quests give 100-200 each."] = "",
	-- {item:12846} Argent Dawn Commission
	["{item:12846}, while you fight the Scourge"] = "",

	-- Step 37: Hallowed Brazier
	-- {object:2160} The Argent Dawn · {area:2268} Light's Hope Chapel · {area:3197} Chillwind Camp · {area:813} Bulwark
	["{object:2160} quartermasters ({area:2268}, {area:3197}, the {area:813}) sell it: 133 gold 33 silver, less with your reputation discount."] = "Это продают интенданты {object:2160} ({area:2268}, {area:3197}, {area:813}): 133 золота 33 серебра, меньше со скидкой за репутацию.",

	-- Step 38: Blackrock Depths and Upper Blackrock Spire
	-- {area:1584} Blackrock Depths
	["{area:1584} and Upper Blackrock Spire"] = "{area:1584} и Верхняя часть пика Черной горы",
	-- {npc:9017} Lord Incendius · {object:174825} Black Anvil (no name in this language: may be words) · {area:1584} Blackrock Depths · {npc:9816} Pyroguard Emberseer
	["{npc:9017} guards the {object:174825} in {area:1584} (a group of five). {npc:9816} is the first boss of Upper Blackrock Spire, a group of up to ten. Each player with the quest loots their own."] = "{npc:9017} охраняет {object:174825} в месте {area:1584} (группа из пяти). {npc:9816} — первый босс Верхней части пика Черной горы, группа до десяти человек. Каждый игрок с заданием получает свою добычу.",
	-- {npc:9816} Pyroguard Emberseer
	["{npc:9816}, Upper Blackrock Spire"] = "{npc:9816}, Верхняя часть пика Черной горы",

	-- Step 39: Duke of Cynders
	-- {zone:1451} Silithus · {item:20422} Twilight Cultist Medallion of Station · {npc:15282} Aurel Goldleaf · {area:3425} Cenarion Hold · {item:14344} Large Brilliant Shard · {item:20432} Signet of Beckoning: Fire · {npc:15206} Duke of Cynders
	-- plural, as words: Greater Wind Stones = {object:180466} Greater Wind Stone · Abyssal Crests = {item:20513} Abyssal Crest
	["The Duke (level 62 elite, bring a group of five) only comes when someone summons him at one of the Twilight's Greater Wind Stones in {zone:1451}: the summoner wears the full Twilight Cultist set (Cowl, Mantle and Robe, from the Twilight cultists of the {zone:1451} camps), carries a {item:20422} ({npc:15282} at {area:3425}: three Abyssal Crests from summoned Templars and a {item:14344}) and a {item:20432}, which calls the {npc:15206} rather than a random Duke. Joining someone else's summon is the quick way: every player with the quest loots their own Cinder."] = "Герцог (элита 62-го уровня, соберите группу из пяти) появляется, только если его призвать у одного из Больших Камней Ветра Сумеречного Молота в зоне {zone:1451}: призывающий носит полный комплект Сумеречного культиста (капюшон, мантия и балахон с сумеречных культистов из лагерей зоны {zone:1451}), имеет {item:20422} ({npc:15282} в месте {area:3425}: три Гребня Бездны с призванных храмовников и {item:14344}) и {item:20432}, который призывает {npc:15206}, а не случайного Герцога. Быстрее присоединиться к чужому призыву: каждый игрок с заданием получает свой Пепел.",

	-- Step 40: Bodley: Components of Importance
	-- {npc:16033} Bodley
	["{npc:16033}'s next task depends on your class: the piece the summoning brazier needs."] = "Следующее задание {npc:16033} зависит от вашего класса: это предмет, нужный для жаровни призыва.",

	-- Step 42: Components of Importance: Soul Ashes of the Banished
	-- {area:896} Purgation Isle · {zone:1424} Hillsbrad Foothills · {item:22229} Soul Ashes of the Banished
	["At {area:896}, the island off the south coast of the {zone:1424}, the Condemned and Cursed undead (level 57-60 elites), thickest by the tower on the hill drop the {item:22229} (usually 5 to 15 kills; they stun, so a healer or dispeller helps). They are elites: bring a friend or two unless your gear is good. It drops only while you have the quest; everyone in the group with it can loot one."] = "В месте {area:896}, на острове у южного побережья зоны {zone:1424}, проклятая и осужденная нежить (элита 57-60-го уровня), гуще всего у башни на холме, роняет {item:22229} (обычно 5-15 убийств; они оглушают, так что лекарь или рассеиватель поможет). Это элита: возьмите одного-двух друзей, если ваша экипировка не хороша. Падает только при наличии задания; каждый в группе с заданием может забрать по одному.",

	-- Step 44: The Left Piece of Lord Valthalak's Amulet
	-- {npc:16033} Bodley · {item:22051} Brazier of Beckoning
	["{npc:16033} gives you a {item:22051}."] = "{npc:16033} дает вам {item:22051}.",

	-- Step 45: The Left Piece of Lord Valthalak's Amulet: Kormok
	-- {npc:16033} Bodley · {item:22052} Brazier of Beckoning · {npc:16118} Kormok · {npc:10508} Ras Frostwhisper · {area:2057} Scholomance · {spell:27688} Bone Shield
	["A dungeon run for a group of five. {npc:16033}'s {item:22052} calls {npc:16118} to {npc:10508}'s room in {area:2057}: clear the room first. Use the brazier there, kill {npc:16118} and loot the piece. He is an elite ogre spirit who keeps raising skeletons: dispel or purge his {spell:27688} and burn him down. After a wipe he stays up: come back without summoning again. Keep the brazier: {npc:16033} wants it back with the piece."] = "Забег в подземелье группой из пяти. {item:22052} от {npc:16033} призывает {npc:16118} в комнату {npc:10508} в подземелье {area:2057}: сначала зачистите комнату. Используйте там жаровню, убейте {npc:16118} и заберите часть. Это элитный дух огра, который постоянно поднимает скелетов: рассеивайте или развеивайте его {spell:27688} и быстро убейте его. После вайпа он остается: возвращайтесь, не призывая его снова. Сохраните жаровню: {npc:16033} хочет получить ее обратно вместе с частью.",
	-- {item:22052} Brazier of Beckoning · {npc:16118} Kormok
	["{item:22052}: summons {npc:16118}"] = "{item:22052}: призывает {npc:16118}",

	-- Step 48: Bloodkelp
	-- {area:2079} Alcaz Island · {zone:1445} Dustwallow Marsh · {npc:16072} Tidelord Rrurgaz
	["The Strashaz naga of {area:2079}, off the north-east coast of {zone:1445}, carry it (level 59-61 elites, and {npc:16072} at 62): bring a friend or two. The Baskets of Bloodkelp on the island give 1 to 3 each without a fight. Swim over from the coast north of Theramore; elite hydras roam the water."] = "Его носят наги Штрашаз в месте {area:2079}, у северо-восточного побережья зоны {zone:1445} (элита 59-61-го уровня и {npc:16072} 62-го): возьмите одного-двух друзей. Корзины с кровавой ламинарией на острове дают по 1-3 штуки без боя. Плывите с побережья к северу от Терамора; в воде бродят элитные гидры.",

	-- Step 51: More Components of Importance: Brilliant Sword of Zealotry
	-- {area:2266} Tyr's Hand · {zone:1423} Eastern Plaguelands · {item:22228} Brilliant Sword of Zealotry
	-- plural, as words: Scarlet Praetorians = {npc:9448} Scarlet Praetorian
	["At {area:2266}, the Scarlet town in the south-east of the {zone:1423}, the Scarlet Praetorians (level 56-57 elites) of its upper courtyard drop the {item:22228} (a rare drop: up to about 50 kills). They are elites: bring a friend or two unless your gear is good. It drops only while you have the quest; everyone in the group with it can loot one."] = "В месте {area:2266}, городе Алого ордена на юго-востоке зоны {zone:1423}, алые преторианцы (элита 56-57-го уровня) верхнего двора роняют {item:22228} (редкая добыча: до 50 убийств). Это элита: возьмите одного-двух друзей, если ваша экипировка не хороша. Падает только при наличии задания; каждый в группе с заданием может забрать по одному.",

	-- Step 54: The Right Piece of Lord Valthalak's Amulet: Jarien and Sothos
	-- {quest:8991} The Right Piece of Lord Valthalak's Amulet · {npc:16101} Jarien · {npc:16102} Sothos
	["{quest:8991}: {npc:16101} and {npc:16102}"] = "{quest:8991}: {npc:16101} и {npc:16102}",
	-- {npc:16033} Bodley · {item:22051} Brazier of Beckoning · {npc:16101} Jarien · {npc:16102} Sothos · {area:2279} Stratholme · {item:21984} Left Piece of Lord Valthalak's Amulet · {item:22048} Lord Valthalak's Amulet
	["A dungeon run for a group of five. {npc:16033}'s {item:22051} calls {npc:16101} and {npc:16102} to Balnazzar's chamber at the end of {area:2279}'s Scarlet side, through the main gate: clear to it first. Use the brazier there, kill {npc:16101} and {npc:16102} and loot the piece. Both are elites: {npc:16101} cleaves, so tank him facing away; {npc:16102} fears. When one falls the other's spirit fights on. Keep the brazier: {npc:16033} wants it back with the piece. Then use the {item:21984} ({npc:16033} gave it back to you) to join the pieces into {item:22048}."] = "Забег в подземелье группой из пяти. {item:22051} от {npc:16033} призывает {npc:16101} и {npc:16102} в покои Бальназара в конце Алой части подземелья {area:2279}, через главные ворота: сначала зачистите путь туда. Используйте там жаровню, убейте {npc:16101} и {npc:16102} и заберите часть. Оба — элита: {npc:16101} бьет рассекающим ударом, так что держите его спиной к группе; {npc:16102} насылает страх. Когда один падает, дух другого продолжает бой. Сохраните жаровню: {npc:16033} хочет получить ее обратно вместе с частью. Затем используйте {item:21984} ({npc:16033} вернул его вам), чтобы соединить части в {item:22048}.",
	-- {item:22051} Brazier of Beckoning · {npc:16101} Jarien · {npc:16102} Sothos
	["{item:22051}: summons {npc:16101} and {npc:16102}"] = "{item:22051}: призывает {npc:16101} и {npc:16102}",
	-- {item:21984} Left Piece of Lord Valthalak's Amulet
	["{item:21984}: joins the pieces"] = "{item:21984}: соединяет части",

	-- Step 56: Final Preparations
	-- {area:1583} Blackrock Spire · {item:13512} Flask of Supreme Power
	-- plural, as words: Blackrock Bracers = {item:22138} Blackrock Bracer · Scarshield Grunts = {npc:9043} Scarshield Grunt
	["40 Blackrock Bracers from the Blackrock orcs of {area:1583} (the Scarshield Grunts in the mountain's halls outside the portal, level 53-54 elites, drop them most often; Upper {area:1583}'s orcs better than Lower's), only while you have the quest, and a {item:13512} (alchemists make it at an alchemy lab; or the auction house)."] = "40 браслетов Черной горы с орков Черной горы в подземелье {area:1583} (чаще всего их роняют бугаи из клана Изрубленного Щита в залах горы перед порталом, элита 53-54-го уровня; орки верхней части {area:1583} лучше нижней), только пока у вас есть задание, и {item:13512} (алхимики делают его у алхимической лаборатории; или на аукционе).",

	-- Step 58: Upper Blackrock Spire: Lord Valthalak
	-- {area:1583} Blackrock Spire · {npc:16042} Lord Valthalak
	["Upper {area:1583}: {npc:16042}"] = "Верхняя часть {area:1583}: {npc:16042}",
	-- {npc:10430} The Beast · {item:22056} Brazier of Beckoning · {npc:16042} Lord Valthalak · {item:22048} Lord Valthalak's Amulet · {quest:8996} Return to Bodley
	["A raid of up to ten in Upper Blackrock Spire. Clear to {npc:10430}'s room and kill {npc:10430}, then use the {item:22056} there to call {npc:16042} (level 63 boss). Kill his shades quickly; in his last phase he hits the whole room hard. Use {item:22048} on his corpse: his spirit appears. Give him the amulet, then take {quest:8996} from him."] = "Рейд до десяти человек в Верхней части пика Черной горы. Зачистите путь до комнаты {npc:10430} и убейте {npc:10430}, затем используйте там {item:22056}, чтобы призвать {npc:16042} (босс 63-го уровня). Быстро убивайте его тени; в последней фазе он сильно бьет всю комнату. Используйте {item:22048} на его трупе: появится его дух. Отдайте ему амулет, затем возьмите у него {quest:8996}.",
	-- {item:22056} Brazier of Beckoning · {npc:10430} The Beast
	["{item:22056}, in {npc:10430}'s room"] = "{item:22056} в комнате {npc:10430}",
	-- {item:22048} Lord Valthalak's Amulet
	["{item:22048}, on his corpse"] = "{item:22048} на его трупе",

	-- Step 59: Bodley: Back to the Beginning
	-- {npc:16033} Bodley · {item:22056} Brazier of Beckoning
	["Hand {npc:16033} the {item:22056}."] = "Отдайте {npc:16033} {item:22056}.",

	-- Step 60: Deliana: Saving the Best for Last
	-- {quest:84199} Saving the Best for Last · {item:16693} Devout Crown · {npc:1853} Darkmaster Gandling · {area:2057} Scholomance · {item:16690} Devout Robe · {npc:10363} General Drakkisath
	["{quest:84199} takes your {item:16693}: {npc:1853} in {area:2057} (about 12%), and your {item:16690}: {npc:10363} in Upper Blackrock Spire (about 11%)."] = "{quest:84199} забирает {item:16693}: {npc:1853} в подземелье {area:2057} (около 12%), и {item:16690}: {npc:10363} в Верхней части пика Черной горы (около 11%).",

	-- Step 61: Mokvar: Saving the Best for Last
	-- {quest:84206} Saving the Best for Last · {item:16693} Devout Crown · {npc:1853} Darkmaster Gandling · {area:2057} Scholomance · {item:16690} Devout Robe · {npc:10363} General Drakkisath
	["{quest:84206} takes your {item:16693}: {npc:1853} in {area:2057} (about 12%), and your {item:16690}: {npc:10363} in Upper Blackrock Spire (about 11%)."] = "{quest:84206} забирает {item:16693}: {npc:1853} в подземелье {area:2057} (около 12%), и {item:16690}: {npc:10363} в Верхней части пика Черной горы (около 11%).",

	-- No longer in the guide (its English changed or it went away): reuse or delete.
	-- ["Polestar's quest data doesn't know Forever's Saving the Best for Last for the {npc:234973} yet, so this guide can't track it: {npc:230319} should offer it now. Take it from her and give her your {item:16693} and {item:16690}."] = "Данные заданий Polestar пока не знают задание Forever «Лучшее напоследок» для {npc:234973}, поэтому гайд не может его отслеживать: {npc:230319} должна предложить его сейчас. Возьмите его у нее и отдайте ей {item:16693} и {item:16690}.",
	-- ["Polestar's quest data doesn't know Forever's Saving the Best for Last for the {npc:235047} yet, so this guide can't track it: {npc:230317} should offer it now. Take it from him and give him your {item:16693} and {item:16690}."] = "Данные заданий Polestar пока не знают задание Forever «Лучшее напоследок» для {npc:235047}, поэтому гайд не может его отслеживать: {npc:230317} должен предложить его сейчас. Возьмите его у него и отдайте ему {item:16693} и {item:16690}.",
	-- ["Saving the Best for Last takes your {item:16693}: {npc:1853} in {area:2057} (about 12%), and your {item:16690}: {npc:10363} in Upper Blackrock Spire (about 11%)."] = "«Лучшее напоследок» требует {item:16693}: {npc:1853} в подземелье {area:2057} (около 12%), и {item:16690}: {npc:10363} в Верхней части пика Черной горы (около 11%).",
	-- ["The Tortured Druids and Sentinels haunt {area:2738} in {zone:1451} (level 55-57, not elite; silithid can join when they die). Place the {item:21946} among the ghosts, pull them into its glow and kill them there, standing in it yourself: ectoplasm only drops from a ghost that dies inside the glow. It lasts a few minutes, then place it again."] = "Измученные друиды и часовые бродят в месте {area:2738} в зоне {zone:1451} (55-57-й уровень, не элита; после их смерти могут появиться силитиды). Поставьте {item:21946} среди призраков, затащите их в его сияние и убейте там, стоя в нем сами: эктоплазма падает только с призрака, погибшего в сиянии. Оно длится несколько минут, затем поставьте снова.",
	-- ["The ghosts and banshees of the {zone:1423} (Unseen Servants, Eyeless Watchers, Death Singers, Hate Shriekers; level 55-59, not elite) drop it; {area:2272} in the north-east is a good spot. The shriekers fear: fight close to the distiller. Place the {item:21946} among the ghosts, pull them into its glow and kill them there, standing in it yourself: ectoplasm only drops from a ghost that dies inside the glow. It lasts a few minutes, then place it again."] = "Его роняют призраки и банши зоны {zone:1423} (незримые слуги, безглазые наблюдатели, певицы смерти, вопящие ненавистницы; 55-59-й уровень, не элита); хорошее место — {area:2272} на северо-востоке. Вопящие пугают: сражайтесь рядом с дистиллятором. Поставьте {item:21946} среди призраков, затащите их в его сияние и убейте там, стоя в нем сами: эктоплазма падает только с призрака, погибшего в сиянии. Оно длится несколько минут, затем поставьте снова.",
	-- ["The {item:22014} is sold only to Honored. Take the {item:12846} ({npc:10840} at {area:3197}, {npc:10839} at the {area:813}, or {npc:11039} at {area:2268}) and wear it: Scourgestones then drop from the Scourge, and the Argent officers take them back for reputation. Every Scourge kill in the Plaguelands counts, {area:2279}'s and {area:2057}'s undead give 5 each up to Honored, and {area:2268}'s dungeon quests give 100-200 each. Polestar's Argent Dawn Reputation guide (Reputation) walks it step by step."] = "{item:22014} продается только при «Уважении». Возьмите {item:12846} ({npc:10840} в месте {area:3197}, {npc:10839} в месте {area:813} или {npc:11039} в месте {area:2268}) и наденьте его: тогда с Плети падают камни Плети, а офицеры Серебряного Рассвета принимают их за репутацию. Считается каждое убийство Плети в Чумных землях, нежить подземелий {area:2279} и {area:2057} дает по 5 до «Уважения», а задания подземелий из места {area:2268} — по 100-200. Гайд Polestar по репутации Серебряного Рассвета (Репутация) проводит по этому шаг за шагом.",
	-- ["The {spell:17735} and {npc:7524} drift around {area:2251} in {zone:1452} (level 54-56, not elite). Place the {item:21946} among the ghosts, pull them into its glow and kill them there, standing in it yourself: ectoplasm only drops from a ghost that dies inside the glow. It lasts a few minutes, then place it again. While you are in {zone:1452}, buy the {item:21939} (40 gold) from {npc:16015}, an imp in the cave at the mouth of {area:2256} in the far south: keep to the right-hand wall to slip past the elite demons in the gorge. {quest:8928} asks for it later, and this saves the trip back."] = "{spell:17735} и {npc:7524} бродят в месте {area:2251} в зоне {zone:1452} (54-56-й уровень, не элита). Поставьте {item:21946} среди призраков, затяните их в его свечение и убивайте там, стоя в нем сами: эктоплазма падает только с призрака, погибшего внутри свечения. Оно длится несколько минут, затем поставьте его снова. Пока вы в зоне {zone:1452}, купите {item:21939} (40 золота) у {npc:16015} — беса в пещере у входа в {area:2256} на крайнем юге: держитесь правой стены, чтобы проскользнуть мимо элитных демонов в ущелье. {quest:8928} потребует его позже, и так вы сэкономите обратный путь.",
	-- ["{npc:16016}'s ghost waits on the bridge before {area:2279}'s main gate, at the north end of the {zone:1423}. Use the {item:22115} there to see him."] = "Призрак {npc:16016} ждет на мосту перед главными воротами {area:2279}, на северной окраине зоны {zone:1423}. Используйте там {item:22115}, чтобы увидеть его.",
	-- ["{npc:16032} finishes the {item:21986}: plant it in the Ring of Law in {area:1584}."] = "{npc:16032} завершает {item:21986}: установите его на Арене Закона в месте {area:1584}.",
	-- ["{npc:16033}'s ghost stands on the ledge before the {area:1583} portal, high inside {area:254}: use the Ghost Revealer there. {quest:8961} wants the {item:21987} ({npc:9017} in {area:1584}), the {item:21988} ({npc:9816} in Upper Blackrock Spire), the {item:21989} (the {npc:15206} in {zone:1451}) and a {item:22014} from the {faction:529}."] = "Призрак {npc:16033} стоит на уступе перед порталом в {area:1583}, высоко внутри {area:254}: используйте там проявитель призраков. Для {quest:8961} нужны {item:21987} ({npc:9017} в месте {area:1584}), {item:21988} ({npc:9816} в Верхней части пика Черной горы), {item:21989} ({npc:15206} в зоне {zone:1451}) и {item:22014} от фракции {faction:529}.",
	-- ["{npc:230317}: Saving the Best for Last"] = "{npc:230317}: Лучшее напоследок",
	-- ["{npc:230319}: Saving the Best for Last"] = "{npc:230319}: Лучшее напоследок",
}
